/* ---- helpers ---- */
window.getLang = function () { return localStorage.getItem('sb-lang') || 'ar'; };
window.T = function (k) { const l = window.getLang(); return (I18N[l] && I18N[l][k]) || (I18N.ar[k]) || k; };

window.applyDir = function (lang) {
  const root = document.documentElement;
  root.lang = lang;
  root.dir = lang === 'ar' ? 'rtl' : 'ltr';
  root.style.setProperty('--dir', lang === 'ar' ? '-1' : '1');
};

window.applyI18n = function (root) {
  const scope = root || document;
  const lang = window.getLang();
  scope.querySelectorAll('[data-i18n]').forEach((el) => { el.textContent = T(el.dataset.i18n); });
  scope.querySelectorAll('[data-i18n-ph]').forEach((el) => { el.placeholder = T(el.dataset.i18nPh); });
  scope.querySelectorAll('[data-i18n-html]').forEach((el) => { el.innerHTML = T(el.dataset.i18nHtml); });
  scope.querySelectorAll('[data-i18n-title]').forEach((el) => { el.title = T(el.dataset.i18nTitle); });
  scope.querySelectorAll('[data-ar][data-en]').forEach((el) => {
    el.textContent = lang === 'ar' ? el.dataset.ar : el.dataset.en;
  });
};

window.setLang = function (lang) {
  localStorage.setItem('sb-lang', lang);
  applyDir(lang);
  applyI18n();
  document.dispatchEvent(new CustomEvent('langchange', { detail: lang }));
};
